import smbus2
import time
import picamera2
from picamera2 import PiRGBStream
from picamera2.config import PiRGBSize
from adafruit_circuitpython_mma8451 import MMA8451
from adafruit_circuitpython_mpu6050 import MPU6050
import paho.mqtt.client as mqtt

# I2C settings
I2C_ADDRESS = 0x40
I2C Bus = 1

# MQTT settings
MQTT_BROKER = 'localhost'
MQTT_PORT = 1883
MQTT_TOPIC = 'measurements'

def read_pca9685():
    try:
        bus = smbus2.SMBus(I2C Bus)
        pca9685 = bus.open(0x40)
        if pca9685 is None:
            print("Error: Unable to open PCA9685 device")
            return None
        try:
            measurement = pca9685.read_byte(0x00)
            return measurement
        except Exception as e:
            print(f"Error reading from PCA9685: {e}")
            return None
    except Exception as e:
        print(f"Error opening I2C bus: {e}")
        return None

def read_mma8451():
    try:
        mma8451 = MMA8451()
        try:
            measurement = mma8451.acceleration
            return measurement
        except Exception as e:
            print(f"Error reading from MMA8451: {e}")
            return None
    except Exception as e:
        print(f"Error opening MMA8451 device: {e}")
        return None

def read_mpu6050():
    try:
        mpu6050 = MPU6050()
        try:
            measurement = mpu6050.acceleration
            return measurement
        except Exception as e:
            print(f"Error reading from MPU6050: {e}")
            return None
    except Exception as e:
        print(f"Error opening MPU6050 device: {e}")
        return None

def main():
    try:
        # Initialize camera
        camera = PiRGBStream(resolution=PiRGBSize(640, 480), framerate=30)
        camera.start()

        # Initialize MQTT client
        client = mqtt.Client()
        client.connect(MQTT_BROKER, MQTT_PORT)

        while True:
            # Read from PCA9685
            pca9685_measurement = read_pca9685()
            if pca9685_measurement is not None:
                # Read from MMA8451
                mma8451_measurement = read_mma8451()
                if mma8451_measurement is not None:
                    # Read from MPU6050
                    mpu6050_measurement = read_mpu6050()
                    if mpu6051_measurement is not None:
                        # Validate measurements
                        if pca9685_measurement is not None and mma8451_measurement is not None and mpu6050_measurement is not None:
                            # Publish measurements to MQTT
                            client.publish(MQTT_TOPIC, f"{pca9685_measurement}, {mma8451_measurement}, {mpu6050_measurement}")
                            print(f"Published measurement: {pca9685_measurement}, {mma8451_measurement}, {mpu6050_measurement}")
                        else:
                            print("Invalid measurement")
                    else:
                        print("Error reading from MPU6050")
                else:
                    print("Error reading from MMA8451")
            else:
                print("Error reading from PCA9685")

            # Wait for 0.15 seconds
            time.sleep(0.15)

        # Clean up
        camera.stop()
        client.disconnect()
    except KeyboardInterrupt:
        print("Exiting cleanly")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

import serial
import time
import threading
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Set up serial connection
try:
    ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1, bytesize=serial.EIGHTBITS, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE)
except serial.SerialException as e:
    logger.error(f"Failed to open serial port: {e}")
    exit(1)

def read_from_serial():
    while True:
        try:
            data = ser.readline().decode('utf-8').strip()
            if data:
                logger.info(data)
                print(data)
        except serial.SerialException as e:
            logger.error(f"Serial read error: {e}")
            break

def main():
    try:
        # Start reading from serial in a separate thread
        read_thread = threading.Thread(target=read_from_serial)
        read_thread.daemon = True  # So that the thread dies when the main program exits
        read_thread.start()

        # Wait for 5 seconds before exiting
        time.sleep(5)

    except KeyboardInterrupt:
        logger.info("Received interrupt signal, exiting")
    except Exception as e:
        logger.error(f"Main program error: {e}")
    finally:
        # Close the serial connection
        try:
            ser.close()
        except serial.SerialException as e:
            logger.error(f"Failed to close serial port: {e}")

if __name__ == "__main__":
    main()

