        logger.error(f"Failed to release MQTT client: {e}")

import time
import logging
import signal
from gpiozero import CPUTimeoutError, OutputDevice
from picamera2 import PiCamera
from adafruit_circuitpython_mcp3008 import MCP3008
import paho.mqtt.client as mqtt

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Set up GPIO
try:
    ultrasonic = OutputDevice(17, 22, 27, initial_value=0)
except CPUTimeoutError:
    logger.error("Failed to initialize GPIO")
    exit(1)

# Set up camera
try:
    camera = PiCamera()
except Exception as e:
    logger.error(f"Failed to initialize camera: {e}")
    exit(1)

# Set up MCP3008
try:
    mcp3008 = MCP3008(0)
except Exception as e:
    logger.error(f"Failed to initialize MCP3008: {e}")
    exit(1)

# Set up MQTT
try:
    client = mqtt.Client()
    client.connect("localhost", 1883)
except Exception as e:
    logger.error(f"Failed to connect to MQTT: {e}")
    exit(1)

# Set up ultrasonic sensor
try:
    ultrasonic.value = 0
except Exception as e:
    logger.error(f"Failed to set ultrasonic value: {e}")
    exit(1)

while True:
    try:
        # Read ultrasonic sensor
        try:
            distance = ultrasonic.value
        except CPUTimeoutError:
            logger.info("Ultrasonic sensor timed out")
            continue

        # Read MCP3008
        try:
            voltage = mcp3008.read(0)
        except Exception as e:
            logger.error(f"Failed to read MCP3008: {e}")
            continue

        # Publish to MQTT
        try:
            client.publish("ultrasonic", str(distance))
            client.publish("mcp3008", str(voltage))
        except Exception as e:
            logger.error(f"Failed to publish to MQTT: {e}")

        # Wait 0.5 seconds
        time.sleep(0.5)
    except KeyboardInterrupt:
        logger.info("Received interrupt, exiting cleanly")
        break
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
        break

# Release hardware resources
try:
    ultrasonic.close()
except Exception as e:
    logger.error(f"Failed to close ultrasonic: {e}")

try:
    camera.close()
except Exception as e:
    logger.error(f"Failed to close camera: {e}")

try:
    mcp3008.close()
except Exception as e:
    logger.error(f"Failed to close MCP3008: {e}")

try:
    client.disconnect()
except Exception as e:
    logger.error(f"Failed to disconnect from MQTT: {e}")
